use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  pub api_desired_settings: Isolette_Thermostat_Rust::DesiredTemperatureSettings,
  pub api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_current_temperature(container.api_current_temperature);
  put_desired_settings(container.api_desired_settings);
  put_regulator_mode(container.api_regulator_mode);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  desired_settings: Isolette_Thermostat_Rust::DesiredTemperatureSettings,
  regulator_mode: Isolette_Thermostat_Rust::ThermostatMode)
{
  put_current_temperature(current_temperature);
  put_desired_settings(desired_settings);
  put_regulator_mode(regulator_mode);
}

/// setter for IN DataPort
pub fn put_current_temperature(value: Isolette_Thermostat_Rust::CurrentTemperature)
{
  *extern_api::IN_current_temperature.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_desired_settings(value: Isolette_Thermostat_Rust::DesiredTemperatureSettings)
{
  *extern_api::IN_desired_settings.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_regulator_mode(value: Isolette_Thermostat_Rust::ThermostatMode)
{
  *extern_api::IN_regulator_mode.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_interface_facts() -> Isolette_Thermostat_Rust::RegulatorInterfaceFacts
{
  return extern_api::OUT_interface_facts.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_regulator_feedback() -> Isolette_Thermostat_Rust::RegulatorFeedback
{
  return extern_api::OUT_regulator_feedback.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_control_basis() -> Isolette_Thermostat_Rust::RegulatorControlBasis
{
  return extern_api::OUT_control_basis.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
